usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Realtime.TranscriptionSessions.New(
		context.TODO(),
		openai.RealtimeTranscriptionSessionNewParams{
			TurnDetection: openai.RealtimeTranscriptionSessionCreateRequestTurnDetection{Type: "server_vad", Threshold: 1, PrefixPaddingMs: 1, SilenceDurationMs: 1},
			InputAudioNoiseReduction: openai.RealtimeTranscriptionSessionCreateRequestInputAudioNoiseReduction{Type: openai.NoiseReductionTypeNearField},
			InputAudioFormat: openai.RealtimeTranscriptionSessionCreateRequestInputAudioFormatPcm16,
			InputAudioTranscription: openai.AudioTranscription{Model: "string", Language: "string", Prompt: "string", Delay: openai.AudioTranscriptionDelayMinimal},
			Include: []string{"item.input_audio_transcription.logprobs"},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
